describe('Search Field Dropdown - Matching Options', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display dropdown with matching options when typing in search field', () => {
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').type('apple');
    cy.get('[data-testid="dropdown-list"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-apple"]').should('contain', 'Apple');
    cy.get('[data-testid="dropdown-item-apple"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-banana"]').should('contain', 'Banana');
    cy.get('[data-testid="dropdown-item-banana"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-orange"]').should('contain', 'Orange');
    cy.get('[data-testid="dropdown-item-orange"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-apple"]').click();
    cy.get('[data-testid="search-input"]').should('have.value', 'apple');
    cy.get('[data-testid="dropdown-list"]').should('not.exist');
    cy.get('[data-testid="search-results"]').should('contain', 'Apple');
  });

  it('should not display dropdown when search field is empty or no matches are found', () => {
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="dropdown-list"]').should('not.exist');
    cy.get('[data-testid="search-input"]').type('xyz123');
    cy.get('[data-testid="dropdown-list"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-xyz123"]').should('not.exist');
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
    cy.get('[data-testid="dropdown-list"]').should('be.visible');
    cy.get('[data-testid="dropdown-item-apple"]').should('not.exist');
    cy.get('[data-testid="dropdown-item-banana"]').should('not.exist');
    cy.get('[data-testid="dropdown-item-orange"]').should('not.exist');
  });
});
